document.addEventListener("DOMContentLoaded",function(){const e=document.querySelector(".wpau-from-address-hint");if(!e)return;const t=e.querySelector(".wpau-dismiss-from-address-hint");if(!t)return;const n=t.href;t.hidden=!0,e.addEventListener("click",function(e){e.target.closest(".notice-dismiss")&&(navigator.sendBeacon?navigator.sendBeacon(n):fetch(n,{credentials:"same-origin"}))})});
